        "css": "* {\n  box-sizing: border-box;\n}\nbody {\n  margin: 0;\n  min-height: 100vh;\n  display: grid;\n  place-items: center;\n  padding: 24px;\n  background: #f0f3eb;\n  color: #2d4034;\n  font-family: system-ui, sans-serif;\n}\nmain {\n  width: min(100%, 420px);\n  padding: 32px;\n  border-radius: 20px;\n  background: white;\n  box-shadow: 0 12px 40px #2433260a;\n}\nh1 {\n  margin: 0 0 12px;\n  font-size: 28px;\n}\np {\n  color: #75826f;\n  line-height: 1.8;\n}\nbutton {\n  padding: 12px 20px;\n  border: 0;\n  border-radius: 8px;\n  background: #356448;\n  color: white;\n  cursor: pointer;\n  font: inherit;\n}\nbutton:hover {\n  background: #294d37;\n}\ninput {\n  width: 100%;\n  padding: 12px;\n  margin: 8px 0 18px;\n  border: 1px solid #dce4d6;\n  border-radius: 8px;\n  font: inherit;\n}\nlabel {\n  font-size: 14px;\n}\na {\n  color: #356448;\n}\nmain {\n  width: min(100%, 900px);\n}\nh1 {\n  font-size: clamp(28px, 5vw, 48px);\n}\n.tag {\n  letter-spacing: 2px;\n  font-size: 10px;\n}\n.features {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 16px;\n  margin-top: 32px;\n}\narticle {\n  padding: 16px;\n  background: #f4f6ef;\n  border-radius: 12px;\n}\n@media (max-width: 540px) {\n  .features {\n    grid-template-columns: 1fr;\n  }\n}\n/* 模板语言切换工具条，为内容预留空间。 */\nbody {\n  border-top: 44px solid transparent;\n}\nhtml {\n  scroll-padding-top: 54px;\n}\n#template-language-controls {\n  box-sizing: border-box;\n  position: fixed;\n  z-index: 1000;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 44px;\n  padding: 7px 16px;\n  display: flex;\n  justify-content: flex-end;\n  align-items: center;\n  background: #fafbf8;\n  border-bottom: 1px solid #dce4d6;\n  color: #356448;\n  font:\n    12px/1.4 system-ui,\n    sans-serif;\n}\n#template-language-toggle {\n  box-sizing: border-box;\n  width: auto;\n  margin: 0;\n  padding: 4px 12px;\n  min-width: 46px;\n  border: 1px solid #cad8c5;\n  border-radius: 5px;\n  background: white;\n  color: #356448;\n  font: inherit;\n  cursor: pointer;\n}\n#template-language-toggle:hover {\n  background: #edf3e8;\n}\n#template-language-toggle:focus-visible {\n  outline: 2px solid #356448;\n  outline-offset: 2px;\n}\n",
        "js": "// 中英文切换：只更新文案，保留输入、事件和页面状态。\nconst languageUI = (function initTemplateLanguage(initial, translations) {\n  let language = initial;\n  const listeners = new Set();\n  const button = document.querySelector(\"#template-language-toggle\");\n  const controls = document.querySelector(\"#template-language-controls\");\n  const bindings = [];\n  const fragments = new Set();\n  const column = initial === \"zh\" ? 0 : 1;\n  const targetColumn = () => (language === \"zh\" ? 0 : 1);\n  const isConnected = (node) => node.isConnected;\n  const isExcluded = (element) =>\n    !element ||\n    controls?.contains(element) ||\n    element.closest(\"script, style, textarea, code, pre\");\n  const inlinePairs = translations.filter((pair) =>\n    pair.some((value) => /<[a-z][\\s\\S]*>/i.test(value)),\n  );\n  const normalize = (html) => {\n    const content = document.createElement(\"template\");\n    content.innerHTML = html;\n    return content.innerHTML.replace(/\\s+/g, \"\");\n  };\n  const inline = new Map(inlinePairs.map((pair) => [normalize(pair[column]), pair]));\n  // 带 br/em 的翻译片段只包含模板内置标记，先绑定整个片段。\n  // 页面输入绝不进入 innerHTML；其它文案按文本节点更新。\n  for (const element of document.body.querySelectorAll(\"*\")) {\n    if (isExcluded(element) || [...fragments].some((parent) => parent.contains(element)))\n      continue;\n    const pair = inline.get(element.innerHTML.replace(/\\s+/g, \"\"));\n    if (!pair) continue;\n    fragments.add(element);\n    bindings.push(() => {\n      if (isConnected(element)) element.innerHTML = pair[targetColumn()];\n    });\n  }\n  const normalizeText = (value) => value.replace(/\\s+/g, \" \").trim();\n  const plain = new Map(\n    translations\n      .filter((pair) => !pair.some((value) => /<[a-z][\\s\\S]*>/i.test(value)))\n      .map((pair) => [normalizeText(pair[column]), pair]),\n  );\n  const keys = [...plain.keys()].filter(Boolean).sort((a, b) => b.length - a.length);\n  const escape = (value) => value.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const pattern = keys.length\n    ? new RegExp(\n        keys.map((key) => key.split(\" \").map(escape).join(\"\\\\s+\")).join(\"|\"),\n        \"g\",\n      )\n    : null;\n  const translate = (value) =>\n    pattern\n      ? value.replace(pattern, (match) => plain.get(normalizeText(match))[targetColumn()])\n      : value;\n  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);\n  let node;\n  while ((node = walker.nextNode())) {\n    const target = node;\n    if (\n      isExcluded(target.parentElement) ||\n      [...fragments].some((parent) => parent.contains(target))\n    )\n      continue;\n    const original = target.nodeValue;\n    if (!keys.some((key) => normalizeText(original).includes(key))) continue;\n    bindings.push(() => {\n      if (isConnected(target)) target.nodeValue = translate(original);\n    });\n  }\n  for (const element of document.body.querySelectorAll(\"*\")) {\n    if (controls?.contains(element) || element.closest(\"script, style, code, pre\"))\n      continue;\n    for (const attribute of [\"placeholder\", \"title\", \"aria-label\"]) {\n      const original = element.getAttribute(attribute);\n      if (original && keys.some((key) => normalizeText(original).includes(key))) {\n        bindings.push(() => {\n          if (isConnected(element)) element.setAttribute(attribute, translate(original));\n        });\n      }\n    }\n  }\n  function update() {\n    document.documentElement.lang = language === \"zh\" ? \"zh-CN\" : \"en\";\n    if (button) {\n      button.textContent = language === \"zh\" ? \"EN\" : \"中文\";\n      button.setAttribute(\n        \"aria-label\",\n        language === \"zh\" ? \"Switch to English\" : \"切换为中文\",\n      );\n    }\n  }\n  button?.addEventListener(\"click\", () => {\n    language = language === \"zh\" ? \"en\" : \"zh\";\n    bindings.forEach((apply) => apply());\n    update();\n    listeners.forEach((listener) => listener());\n  });\n  update();\n  return {\n    t: (zh, en) => (language === \"zh\" ? zh : en),\n    onChange: (listener) => listeners.add(listener),\n    get language() {\n      return language;\n    },\n  };\n})(\"zh\", [\n  [\"为小小的想法而生\", \"MADE FOR SMALL IDEAS\"],\n  [\"让每个想法，都有起点。\", \"Give every idea a beginning.\"],\n  [\n    \"拖动预览尺寸，观察卡片如何重新排列。\",\n    \"Resize the preview and watch the cards rearrange.\",\n  ],\n  [\"写下想法\", \"Write it down\"],\n  [\"动手尝试\", \"Try it out\"],\n  [\"分享成果\", \"Share the result\"],\n]);\n\n// 调整预览宽度，观察响应式布局。 / Resize the preview to explore the layout.\n"
